package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_previousSibling_TriageGen2Test {

    private Node parentNode;
    private Node childNode1;
    private Node childNode2;
    private Node childNode3;

    @Before
    public void setUp() {
        Document doc = new Document("");
        parentNode = new Element(Tag.valueOf("div"), "").parent();
        childNode1 = new Element(Tag.valueOf("p"), "").parent();
        childNode2 = new Element(Tag.valueOf("span"), "").parent();
        childNode3 = new Element(Tag.valueOf("a"), "").parent();

        parentNode.appendChild(childNode1);
        parentNode.appendChild(childNode2);
        parentNode.appendChild(childNode3);

        childNode1.setParentNode(parentNode);
        childNode2.setParentNode(parentNode);
        childNode3.setParentNode(parentNode);

        childNode1.setSiblingIndex(0);
        childNode2.setSiblingIndex(1);
        childNode3.setSiblingIndex(2);
    }

    @Test
    public void testPreviousSibling_FirstChild() {
        Node result = childNode1.previousSibling();
        assertNull(result);
    }

    @Test
    public void testPreviousSibling_MiddleChild() {
        Node result = childNode2.previousSibling();
        assertEquals(childNode1, result);
    }

    @Test
    public void testPreviousSibling_LastChild() {
        Node result = childNode3.previousSibling();
        assertEquals(childNode2, result);
    }

    @Test(expected = NullPointerException.class)
    public void testPreviousSibling_NullParent() {
        Node orphanNode = new Element(Tag.valueOf("b"), "").parent();
        orphanNode.setSiblingIndex(0);
        orphanNode.previousSibling();
    }

    @Test
    public void testPreviousSibling_EmptyParent() {
        Node emptyParent = new Element(Tag.valueOf("div"), "").parent();
        Node result = emptyParent.previousSibling();
        assertNull(result);
    }

    @Test
    public void testPreviousSibling_OnlyChild() {
        Node onlyChild = new Element(Tag.valueOf("p"), "").parent();
        onlyChild.setParentNode(parentNode);
        onlyChild.setSiblingIndex(0);

        Node result = onlyChild.previousSibling();
        assertNull(result);
    }
}
